int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sock *sk = sock->sk;
    int ret;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (sk->sk_receive_queue.all == NULL) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;
        else
            return -EWOULDBLOCK;
    }

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    ret = sock_get_datagram(sk, msg, len, flags);
    if (ret < 0)
        return ret;

    if (sock->type == SOCK_DGRAM)
        sock_copy_from_skb(msg, sk->sk_receive_queue.head, ret);

    sock_dequeue(sk);

    return ret;
}

ssize_t sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    ssize_t res = -EAGAIN;

    if (sk->sk_state == TCP_CLOSE)
        return 0;

    if (sk->sk_data_qlen == 0) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;
        // Block and wait for data if non-blocking is not set
        // (Simplified for example purposes)
        return -EAGAIN;
    }

    struct sk_buff *skb = skb_peek(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (flags & MSG_OOB) {
        // Handle out-of-band data
        skb = skb_peek_oob(&sk->sk_receive_queue);
        if (!skb)
            return -ENOENT;
    }

    res = skb->len;
    if (len < (size_t)res)
        res = len;

    if (sock->type == SOCK_DGRAM) {
        msg->msg_name = (void *)&skb->cb;
        msg->msg_namelen = sizeof(struct sockaddr);
    }

    memcpy(msg->msg_data, skb->data, res);

    if (sock->type == SOCK_STREAM)
        __skb_pull(skb, res);
    else
        skb_unlink(skb, &sk->sk_receive_queue);

    return res;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags) {
    struct sock *sk = sock->sk;
    int ret;
    size_t copied = 0;

    if (sk->sk_state == TCP_CLOSE && !(flags & MSG_DONTWAIT))
        return -ENOTCONN;

    if (skb_queue_empty(&sk->sk_receive_queue)) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;
        while (skb_queue_empty(&sk->sk_receive_queue)) {
            if (signal_pending(current))
                return -EINTR;
            schedule();
        }
    }

    struct sk_buff *skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (sock->type == SOCK_DGRAM) {
        msg->msg_name = (void *)&skb->raddr;
        msg->msg_namelen = sizeof(skb->raddr);
    }

    ret = skb->len;
    if (len < skb->len)
        ret = -EMSGSIZE;

    if (copy_to_iter(skb->data, ret, msg->msg_iter) != ret)
        return -EFAULT;

    copied = ret;

    if (sock->type == SOCK_DGRAM)
        kfree_skb(skb);
    else
        skb_free(skb);

    return copied;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (sock->type == SOCK_DGRAM) {
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb) {
            return -EAGAIN;
        }
    } else {
        skb = skb_recv_datagram(sock->sk, flags, &err);
        if (!skb) {
            return err;
        }
    }

    copied = skb->len;
    if (len < copied) {
        if (!(flags & MSG_TRUNC)) {
            copied = len;
        } else {
            msg->msg_flags |= MSG_TRUNC;
        }
    }

    if (sock->type == SOCK_DGRAM && msg->msg_name) {
        struct sockaddr *addr = (struct sockaddr *)skb->cb;
        memcpy(msg->msg_name, addr, sock->sk->sk_socket->ops->addr_len);
    }

    if (sock->type == SOCK_DGRAM) {
        if (copied < skb->len) {
            skb_trim(skb, 0);
            skb_queue_head(&sock->sk->sk_receive_queue, skb);
        } else {
            kfree_skb(skb);
        }
    }

    memcpy(msg->msg_data, skb->data, copied);
    msg->msg_data += copied;
    msg->msg_size += copied;

    return copied;
}

ssize_t sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    ssize_t res;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (sk->sk_receive_queue.head == NULL) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;
        while (sk->sk_receive_queue.head == NULL)
            schedule();
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (sock->type == SOCK_DGRAM && skb->cb)
        memcpy(&msg->msg_name, skb->cb, sizeof(*msg->msg_name));

    res = skb->len;
    if (len < skb->len)
        res = -EMSGSIZE;
    else
        memcpy(msg->msg_iov->iov_base, skb->data, skb->len);

    if (sock->type == SOCK_STREAM)
        kfree_skb(skb);
    else
        skb_queue_head(&sk->sk_receive_queue, skb);

    return res;
}
